"""ToolSandbox catalog and official CPU execution; live protocol remains pending."""

import json
import random
import sys
import time
from pathlib import Path

from openai import InternalServerError

from ..advice import AdvisorServiceError, make_advisor
from ..attempt import mark_scoring, record_attempt
from ..client import QwenClient, SimulatorClient, is_service_error
from ..config import WORKSPACE_ROOT, advisor_type
from ..cost import costs
from ..io import append_json, write_json
from .toolsandbox_scores import validate_score

# Exact variants generated by the pinned official registry, not fuzzy ID stripping.
VARIANTS = (
    "",
    "_3_distraction_tools",
    "_10_distraction_tools",
    "_all_tools",
    "_3_distraction_tools_tool_description_scrambled",
    "_3_distraction_tools_arg_type_scrambled",
    "_3_distraction_tools_arg_description_scrambled",
    "_3_distraction_tools_tool_name_scrambled",
)


def configure(config, runtime):
    source = WORKSPACE_ROOT / config["benchmark"]["path"]
    sys.path.insert(0, str(source))
    import tool_sandbox

    if (
        Path(tool_sandbox.__file__).resolve()
        != (source / "tool_sandbox/__init__.py").resolve()
    ):
        raise ValueError("ToolSandbox import must use the pinned checkout")
    from .toolsandbox_currency import install

    install()


def catalog(seed):
    from tool_sandbox.common.execution_context import ScenarioCategories
    from tool_sandbox.common.tool_discovery import ToolBackend
    from tool_sandbox.scenarios import named_scenarios

    # Official CLI seeds Python's RNG before creating/shuffling all variants.
    previous = random.getstate()
    try:
        random.seed(seed)
        scenarios = named_scenarios(preferred_tool_backend=ToolBackend.DEFAULT)
    finally:
        random.setstate(previous)
    originals = [
        name
        for name, scenario in scenarios.items()
        if ScenarioCategories.NO_DISTRACTION_TOOLS in scenario.categories
    ]
    families = {}
    for original in originals:
        for suffix in VARIANTS:
            name = original + suffix
            if name in families:
                raise ValueError(f"ambiguous official augmentation family: {name}")
            families[name] = (original, suffix[1:] if suffix else "original")
    if families.keys() != scenarios.keys():
        raise ValueError(
            "official scenario catalog and exact augmentation families differ"
        )
    return {
        name: {
            "scenario": scenario,
            "family_id": families[name][0],
            "variant": families[name][1],
            "categories": [str(category) for category in scenario.categories],
        }
        for name, scenario in scenarios.items()
    }


def load_tasks(config):
    loaded = catalog(config["protocol"]["scenario_seed"])
    selected = config["task_ids"]["scenarios"]
    if selected == "all":
        selected = list(loaded)
    if not set(selected) <= loaded.keys():
        raise ValueError("unknown canonical ToolSandbox scenario ID")
    tasks = {("scenarios", name): loaded[name] for name in selected}
    return tasks, dict.fromkeys(tasks)


@record_attempt
def run_episode(
    config,
    item,
    task,
    ground_truth,
    directory,
    *,
    pa_tool_identity=None,
    client_factory=QwenClient,
    user_client_factory=SimulatorClient,
    advisor_factory=make_advisor,
):
    if config["protocol"]["mode"] == "cpu_only":
        raise ValueError("ToolSandbox CPU preview cannot execute an episode")
    from ..pa_tool import load_projection
    from .toolsandbox_participants import ConfiguredUser, GuidedAgent

    policy = config["conditions"][item["condition"]]
    settings = config["executors"][policy["executor"]]
    directory = Path(directory)
    sink = lambda kind, value: append_json(
        directory / "diagnostics" / f"{kind}.jsonl", value
    )
    client = user_client = advisor = agent = None
    try:
        client = client_factory(settings, sink)
        user_client = user_client_factory(config["user_simulator"], sink)
        if "advisor" in policy:
            advisor = advisor_factory(
                config["advisors"][policy["advisor"]], sink, advisors=config["advisors"]
            )
        agent = GuidedAgent(
            client=client,
            settings=settings,
            policy=policy,
            advisor_client=advisor,
            event_sink=sink,
            projection=load_projection(
                config, item, expected_identity=pa_tool_identity
            ),
        )
        user = ConfiguredUser(client=user_client)
        return evaluate_scenario(
            task,
            item["task_id"],
            directory,
            agent=agent,
            user=user,
            config=config,
            item=item,
        )
    except Exception as exc:
        path = directory / "episode.json"
        if not path.exists():
            write_json(
                path,
                {
                    **item,
                    "success": None,
                    "official_scored": False,
                    "failure_kind": "service_error"
                    if (
                        is_service_error(exc)
                        and not isinstance(exc, InternalServerError)
                    )
                    else "unexpected_error",
                    "decision_steps": 0,
                    "tool_call_count": 0,
                    "duration_seconds": None,
                    "response_anomalies": [],
                    "cost": costs(
                        client,
                        agent,
                        user_client,
                        advisor_type=advisor_type(config, item["condition"]),
                        advisor_requests=advisor.records if advisor else (),
                    ),
                },
            )
        row = json.loads(path.read_text())
        if row["failure_kind"] in ("service_error", "user_simulator_error"):
            return row
        raise
    finally:
        for resource in (client, user_client, advisor):
            if resource is not None:
                resource.close()


def evaluate_scenario(task, name, directory, *, agent, user, config=None, item=None):
    """Run injected participants through the official loop, with no exception-to-zero rule.

    Intended for CPU fixtures until the live protocol is approved. The caller owns
    the clients. Official state is process-global: never run episodes in threads.
    """
    from attrs import asdict
    from tool_sandbox.common.execution_context import (
        DatabaseNamespace,
        RoleType,
        new_context,
    )
    from tool_sandbox.roles.execution_environment import ExecutionEnvironment

    if (
        agent.decision_steps
        or agent.advisor_records
        or agent.reasoning_history
        or agent.client.records
        or user.client.records
        or agent.normalizations
        or user.normalizations
    ):
        raise ValueError(
            "each ToolSandbox episode requires fresh participants and clients"
        )
    directory = Path(directory)
    if config is None:
        directory.mkdir(parents=True, exist_ok=False)
    scenario = task["scenario"]
    if config is not None:
        from tool_sandbox.common.scenario import Scenario

        class RecordedScenario(Scenario):
            def play(self, *args, **kwargs):
                context = super().play(*args, **kwargs)
                mark_scoring(directory)
                write_json(
                    directory / "trajectory.json",
                    {
                        "partial": False,
                        "context": f"official/trajectories/{name}/execution_context.json",
                    },
                )
                return context

        scenario = RecordedScenario(
            scenario.starting_context,
            scenario.evaluation,
            scenario.max_messages,
            scenario.categories,
        )
    row = {
        "task_id": name,
        "family_id": task["family_id"],
        "variant": task["variant"],
        "categories": task["categories"],
        "official_scored": False,
        "similarity": None,
        "milestone_similarity": None,
        "minefield_similarity": None,
        "turn_count": None,
        "termination_reason": None,
    }
    if config is not None:
        row.update(
            **item,
            success=None,
            failure_kind=None,
            response_anomalies=[],
            tool_call_count=None,
        )
    started = time.perf_counter()
    interrupted = False
    try:
        with new_context(scenario.starting_context):
            result = scenario.play_and_evaluate(
                roles={
                    RoleType.AGENT: agent,
                    RoleType.USER: user,
                    RoleType.EXECUTION_ENVIRONMENT: ExecutionEnvironment(),
                },
                output_directory=directory / "official",
                scenario_name=name,
            )
        score = asdict(result.evaluation_result)
        score["similarity"] = result.evaluation_result.similarity
        validate_score(score)
        write_json(directory / "score.json", score)
        db = result.ending_context.get_database(DatabaseNamespace.SANDBOX)
        row.update(
            official_scored=True,
            **{
                field: score[field]
                for field in (
                    "similarity",
                    "milestone_similarity",
                    "minefield_similarity",
                    "turn_count",
                )
            },
            termination_reason=(
                "message_limit"
                if db["conversation_active"][-1]
                else "user_end_conversation"
            ),
        )
        if config is not None:
            row["official_score"] = {"metric": "similarity", "value": row["similarity"]}
            # Generated executor calls, including any still pending at the message
            # limit; this does not measure completed environment executions.
            row["tool_call_count"] = sum(
                len(record["response"]["choices"][0]["message"].get("tool_calls") or [])
                for record in agent.client.records
                if record["response"] is not None
            )
    except BaseException as exc:
        interrupted = not isinstance(exc, Exception)
        from ..pa_tool import InterfaceViolation

        if config is not None:
            phase = json.loads((directory / "diagnostics/attempt.json").read_text())[
                "phase"
            ]
            row["failure_kind"] = (
                "scoring_error"
                if phase == "scoring"
                else "interrupted"
                if interrupted
                else exc.record["status"]
                if isinstance(exc, AdvisorServiceError)
                else "service_error"
                if (is_service_error(exc) and not isinstance(exc, InternalServerError))
                else "user_simulator_error"
                if getattr(exc, "diagnostics", {}).get("role") == "user_simulator"
                else "unexpected_error"
            )
            if phase == "inference" and isinstance(exc, InterfaceViolation):
                row.update(
                    success=False,
                    failure_kind="executor_response_error",
                    termination_reason="executor_response_error",
                )
        write_json(
            directory / "diagnostics/failure.json",
            {"type": type(exc).__name__, "message": str(exc)},
        )
        if config is None or not isinstance(exc, InterfaceViolation):
            raise
    finally:
        row.update(
            decision_steps=agent.decision_steps,
            response_normalizations={
                "executor": dict(agent.normalizations),
                "user_simulator": dict(user.normalizations),
            },
            cost=costs(
                agent.client,
                agent,
                user.client,
                advisor_type=(
                    advisor_type(config, item["condition"])
                    if config is not None
                    else "jev_local"
                    if agent.policy["advice"] in ("prefer", "gate")
                    else None
                ),
                advisor_requests=agent.advisor_client.records
                if config is not None and agent.advisor_client
                else (),
            ),
            duration_seconds=time.perf_counter() - started,
        )
        row["cost"]["accounting_complete"] = not interrupted
        write_json(directory / "episode.json", row)
    return row


def score_saved(config, item, task, ground_truth, directory):
    from attrs import asdict
    from tool_sandbox.common.execution_context import ExecutionContext, new_context

    directory = Path(directory)
    pointer = json.loads((directory / "trajectory.json").read_text())
    expected = f"official/trajectories/{item['task_id']}/execution_context.json"
    if pointer != {"partial": False, "context": expected}:
        raise ValueError("ToolSandbox recovery requires the complete canonical context")
    context = ExecutionContext.from_dict(json.loads((directory / expected).read_text()))
    path = directory / "score.json"
    if path.exists():
        score = json.loads(path.read_text())
    else:
        with new_context(context):
            result = task["scenario"].evaluation.evaluate(
                execution_context=context, max_turn_count=task["scenario"].max_messages
            )
        score = asdict(result)
        score["similarity"] = result.similarity
        validate_score(score)
        write_json(path, score)
    validate_score(score)
    from tool_sandbox.common.execution_context import DatabaseNamespace

    active = context.get_database(DatabaseNamespace.SANDBOX)["conversation_active"][-1]
    return {
        "success": None,
        "family_id": task["family_id"],
        "variant": task["variant"],
        "categories": task["categories"],
        "termination_reason": "message_limit" if active else "user_end_conversation",
        "official_score": {"metric": "similarity", "value": score["similarity"]},
        **{
            name: score[name]
            for name in (
                "similarity",
                "milestone_similarity",
                "minefield_similarity",
                "turn_count",
            )
        },
    }
